def compute(vars):
    value = vars["v1"] + vars["v2"]
    return {
        "value": value,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "two_year_total": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
